bounded_host_request.command:
set -eu
python3 - <<'PY'
import subprocess,json,urllib.request
rid='run_mvaxg8be_1099f77b3b'
code="""const {RuntimeEvidenceStore}=require('/app/server/runtime-evidence.js');const s=new RuntimeEvidenceStore('/app/runtime');const d=s.list('run_mvaxg8be_1099f77b3b',{types:['ai_invocation'],limit:40});console.log(JSON.stringify(d.slice(0,30).map(x=>{const p=x.payload||{};return{at:x.created_at,role:p.role,model:p.model,phase:p.phase,kind:p.event_kind,elapsed_ms:p.elapsed_ms,queue_wait_ms:p.queue_wait_ms,upstream_wait_ms:p.upstream_wait_ms,backend_progress:p.backend_progress,continuation:p.continuation_assessment,failure:p.failure_code}})))"""
p=subprocess.run(['docker','exec','debug-ai-debug-ai-1','node','-e',code],capture_output=True,text=True,timeout=18)
data={'run_id':rid,'docker_exec_code':p.returncode}
if p.returncode==0:
 try:data['events']=json.loads(p.stdout)
 except ValueError:data['error']='INVALID_TELEMETRY_JSON'
else:data['error']=p.stderr[-150:]
try:
 with urllib.request.urlopen('http://127.0.0.1:8787/v1/status/'+rid,timeout=5) as r:o=json.load(r)
 d=o.get('durable') or {};c=d.get('workflow_cursor') or {}
 data['status']={'job_status':d.get('job_status'),'step':c.get('step_id'),'phase':c.get('step_phase'),'generation':d.get('generation')}
except Exception as e:data['status_error']=type(e).__name__
body='DEBUGAI_LIVE_ROLE_INVOCATION_TELEMETRY\n'+json.dumps(data,ensure_ascii=False,indent=2)
g=subprocess.run(['gh','api','-X','POST','repos/seigo-gace/debug-ai/issues/41/comments','-f','body='+body],capture_output=True,text=True,timeout=28)
if g.returncode:raise SystemExit('GH_POST_FAILED')
print('ROLE_TELEMETRY_COMMENT='+json.loads(g.stdout)['html_url'])
PY
